def observation_helpers():
 import types
 values=[]
 for name,text in(('_trusted_observation_profile',OBSERVATION_SOURCE),('_trusted_inspect_export',INSPECT_STDERR_SOURCE)):
  m=types.ModuleType(name);m.__file__='<source-owned-'+name+'>';m._CONTROL_SOURCE=text;exec(compile(text,m.__file__,'exec'),vars(m));values.append(m)
 return tuple(values)

def observation_fused():
 prefix="import types as _observation_types\n_observation_module=_observation_types.ModuleType('_source_owned_observation')\nexec(compile("+repr(OBSERVATION_SOURCE)+",'<source-owned-observation>','exec'),vars(_observation_module))\n_observation=_observation_module.ObservationProfile607()\n"+OBSERVATION_BINDING_SOURCE+'\n'
 changes=((" roots,caps=module.roots,module.caps"," module=_observation_prepare(module)\n roots,caps=module.roots,module.caps"),(" install_copy_substages(module)\n return module"," install_copy_substages(module)\n return _observation_install(module)"))
 text=FUSED_OBSERVER
 for before,after in changes:need(text.count(before)==1,'one profiled private binding seam');text=text.replace(before,after,1)
 out=prefix+text;back=out.removeprefix(prefix)
 for before,after in reversed(changes):need(back.count(after)==1,'one profiled private binding inverse');back=back.replace(after,before,1)
 need(back==FUSED_OBSERVER,'whole c14 fused helper remains held behind profiling bindings');compile(out,'<profiled-fused-helper>','exec');return out

_observation_parent_backend=rendered_backend
_observation_parent_lifecycle=lifecycle

def rendered_backend(source,*,inspect_profile=False):
 raw,ledger=_observation_parent_backend(source,inspect_profile=inspect_profile)
 if inspect_profile!=INSPECT_CAPACITY_PROFILE:return raw,ledger
 before=repr(FUSED_OBSERVER).encode();after=repr(observation_fused()).encode();need(raw.count(before)==1,'one selected backend fused literal');out=raw.replace(before,after,1);need(out.replace(after,before,1)==raw,'whole selected c14 backend inverse')
 owned=dict(ledger['owned_inspect_validation'],derived_backend=pin(out));ledger=dict(ledger,owned_inspect_validation=owned,observation_profile=dict(parent_backend=pin(raw),backend=pin(out),profiler=pin(OBSERVATION_SOURCE.encode()),exporter=pin(INSPECT_STDERR_SOURCE.encode()),scope='BOUNDED_SCALAR_DATA_NO_TRAVERSAL_OR_CLOCK_CHANGE',native_fit='NOT_ESTABLISHED'))
 return out,ledger

def lifecycle(raw,*,inspect_profile=False):
 before=_observation_parent_lifecycle(raw,inspect_profile=inspect_profile)
 if inspect_profile!=INSPECT_CAPACITY_PROFILE:return before
 _,E=observation_helpers();out,seams=E.lifecycle(before,INSPECT_STDERR_SOURCE)
 back=out.decode()
 for row in reversed(seams):need(back.count(row['after'])==1,'one selected lifecycle export inverse');back=back.replace(row['after'],row['before'],1)
 need(back.encode()==before,'whole c14 selected lifecycle inverse');return out
